    # Handle empty string
    if not json_str or json_str.strip() == '':
        return pd.DataFrame()

    try:
        # Load JSON string into dictionary
        data = json.loads(json_str)
    except (json.JSONDecodeError, ValueError, TypeError):
        return pd.DataFrame()

    # If not a dictionary, return empty DataFrame
    if not isinstance(data, dict):
        return pd.DataFrame()

    # Normalize the dictionary by doubling numerical values
    normalized_data = {}
    has_list = False

    for key, value in data.items():
        if isinstance(value, (int, float)):
            # Double numerical values and convert to float
            normalized_data[key] = float(value) * 2
        elif isinstance(value, list):
            # Handle lists of values
            has_list = True
            normalized_list = []
            for item in value:
                if isinstance(item, (int, float)):
                    normalized_list.append(float(item) * 2)
                elif isinstance(item, str):
                    # Try to extract number from string
                    match = re.search(r'-?\d+\.?\d*', item)
                    if match:
                        normalized_list.append(float(match.group()) * 2)
                    else:
                        # If not a number, keep as string
                        normalized_list.append(item)
                else:
                    # For other types, keep as is
                    normalized_list.append(item)
            normalized_data[key] = normalized_list
        elif isinstance(value, str):
            # Try to extract number from string
            match = re.search(r'-?\d+\.?\d*', value)
            if match:
                normalized_data[key] = float(match.group()) * 2
            else:
                # If not a number, keep as string
                normalized_data[key] = value
        else:
            # For other types, keep as is
            normalized_data[key] = value

    # If there are lists, convert all scalar values to single-element lists
    if has_list:
        for key in normalized_data:
            if not isinstance(normalized_data[key], list):
                normalized_data[key] = [normalized_data[key]]

    # Create DataFrame from normalized dictionary
    if not normalized_data:
        return pd.DataFrame()

    try:
        df = pd.DataFrame(normalized_data)
        return df
    except Exception:
        return pd.DataFrame()

